const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define region - southern Iberian Peninsula (cropland areas)
  const region = ee.Geometry.Polygon([
    [[-8.0, 36.0], [-8.0, 38.5], [-5.5, 38.5], [-5.5, 36.0], [-8.0, 36.0]]
  ]);

  // 2. Load MODIS NDVI data (16-day composite, 250m resolution)
  const modisNDVI = ee.ImageCollection('MODIS/061/MOD13Q1')
    .select('NDVI');

  // Quality masking function
  function maskQuality(image) {
    const qa = image.select('SummaryQA');
    const mask = qa.eq(0); // 0 = good quality
    return image.updateMask(mask);
  }

  // 3. Get 2023 data (March 25 - April 23)
  const ndvi2023 = ee.ImageCollection('MODIS/061/MOD13Q1')
    .filterBounds(region)
    .filterDate('2023-03-25', '2023-04-24')
    .map(maskQuality)
    .select('NDVI');

  const count2023 = ndvi2023.size().getInfo();
  console.log(`2023 Images found: ${count2023}`);

  if (count2023 === 0) {
    console.log('No MODIS data for 2023 period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Get 2000-2010 baseline (same date range each year)
  const years = ee.List.sequence(2000, 2010);

  const baselineImages = years.map(function(year) {
    const startDate = ee.Date.fromYMD(year, 3, 25);
    const endDate = ee.Date.fromYMD(year, 4, 24);

    return ee.ImageCollection('MODIS/061/MOD13Q1')
      .filterBounds(region)
      .filterDate(startDate, endDate)
      .map(maskQuality)
      .select('NDVI')
      .mean();
  });

  const baselineCol = ee.ImageCollection.fromImages(baselineImages);
  const countBaseline = baselineCol.size().getInfo();
  console.log(`Baseline years processed: ${countBaseline}`);

  if (countBaseline === 0) {
    console.log('No baseline data found.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Calculate mean NDVI for both periods
  const mean2023 = ndvi2023.mean();
  const meanBaseline = baselineCol.mean();

  // 6. Get statistics with pixel count
  const stats2023 = mean2023.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const statsBaseline = meanBaseline.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const ndvi2023Val = stats2023.NDVI_mean;
  const pixels2023 = stats2023.NDVI_count;
  const ndviBaselineVal = statsBaseline.NDVI_mean;
  const pixelsBaseline = statsBaseline.NDVI_count;

  console.log(`2023 NDVI: ${ndvi2023Val !== null ? (ndvi2023Val * 0.0001).toFixed(4) : 'null'}, Valid pixels: ${pixels2023 || 0}`);
  console.log(`Baseline NDVI (2000-2010): ${ndviBaselineVal !== null ? (ndviBaselineVal * 0.0001).toFixed(4) : 'null'}, Valid pixels: ${pixelsBaseline || 0}`);

  // 7. Validation
  if (pixels2023 === 0 || pixelsBaseline === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (ndvi2023Val === null || ndviBaselineVal === null) {
    console.log('Calculation returned null values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // MODIS NDVI has scale factor 0.0001, range -2000 to 10000
  const ndvi2023Scaled = ndvi2023Val * 0.0001;
  const ndviBaselineScaled = ndviBaselineVal * 0.0001;

  if (ndvi2023Scaled < -1 || ndvi2023Scaled > 1 || ndviBaselineScaled < -1 || ndviBaselineScaled > 1) {
    console.log('NDVI values out of valid range.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Compare and answer
  const difference = ndvi2023Scaled - ndviBaselineScaled;
  console.log(`Difference (2023 - Baseline): ${difference.toFixed(4)}`);

  if (ndvi2023Scaled > ndviBaselineScaled) {
    console.log('Crops were healthier in 2023 compared to 2000-2010 baseline.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Crops were not healthier in 2023 compared to baseline.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
